def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marker = max((value for value in counts if value != background), key=lambda value: counts[value])
    out = [row[:] for row in grid]

    def fill_runs(line, write):
        i = 0
        while i < len(line):
            if line[i] != background:
                i += 1
                continue
            start = i
            while i < len(line) and line[i] == background:
                i += 1
            if (i - start <= 6 and start > 0 and i < len(line)
                    and line[start - 1] == marker and line[i] == marker):
                for k in range(start, i):
                    write(k)

    for r in range(h):
        fill_runs(grid[r], lambda c, r=r: out[r].__setitem__(c, 2))
    for c in range(w):
        fill_runs([grid[r][c] for r in range(h)], lambda r, c=c: out[r].__setitem__(c, 2))
    # A close pair offset by two rows and one column has one intervening
    # grid cell on its rasterized straight path.
    for r in range(h - 2):
        for c in range(w):
            for dc in (-1, 1):
                cc = c + dc
                if 0 <= cc < w and grid[r][c] == marker and grid[r + 2][cc] == marker:
                    middle_c = min(c, cc)
                    if grid[r + 1][middle_c] == background:
                        out[r + 1][middle_c] = 2
    return out

